snippet_css:
:root{
  --bg: #F5F5F7;
  --fg: #1D1D1F;
  --muted: #5F5F64;
  --surface: #FFFFFF;
  --border: rgba(29,29,31,.12);
  --accent: #0071E3;
  --accent-fg: #FFFFFF;
  --accent-grad: linear-gradient(120deg,#0071E3,#5EA8FF);
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 8px 24px rgba(29,29,31,.08);
  --btn-shadow: 0 2px 6px rgba(0,113,227,.28);
  --art-bg: linear-gradient(135deg,#E0F0FF,#fff 60%,#E8E0FF);
  --media-bg: linear-gradient(135deg,#E0F0FF,#fff);
  --cta-bg: linear-gradient(120deg,#FFE3EC,#E8E0FF 50%,#DDF6EC);
  --input-bg: #FFFFFF;
  --ok: #1B8A45;
  --warn: #C0392B;
  --font-display: Inter,'Noto Sans TC',sans-serif;
  --font-body: Inter,'Noto Sans TC',sans-serif;
  --font-mono: ui-monospace,'SFMono-Regular',monospace;
  --focus-ring: var(--accent);
}

